import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
# ball signature: yellow (R>140,G>110,B<80) OR strong blue (B>100, B>R+30, B>G+20)
R,G,B = d[:,:,:,0],d[:,:,:,1],d[:,:,:,2]
yellow = (R>140)&(G>110)&(B<90)
blue = (B>100)&(B>R+25)&(B>G+15)
mask = yellow|blue
cent=[]
for t in range(96):
    ys,xs=np.nonzero(mask[t])
    if len(xs)>0:
        cent.append((xs.mean(),ys.mean(),len(xs),xs.min(),xs.max(),ys.min(),ys.max()))
    else:
        cent.append(None)
for t,c in enumerate(cent):
    if c: print(t, 'cx=%.1f cy=%.1f n=%d x[%d,%d] y[%d,%d]'%c)
    else: print(t,'NONE')
\""

